def is_majority(arr, n, x):
    """
    Return True if x occurs more than n/2 times in the first n elements
    of the sorted array arr.
    """
    if arr is None:
        return False

    try:
        n = int(n)
    except (TypeError, ValueError, OverflowError):
        return False

    if n <= 0:
        return False

    n = min(n, len(arr))
    if n <= 0:
        return False

    # A strict majority in a sorted array must occupy the middle position.
    if arr[n // 2] != x:
        return False

    # Find the first occurrence of x.
    low, high = 0, n
    while low < high:
        mid = (low + high) // 2
        if arr[mid] < x:
            low = mid + 1
        else:
            high = mid
    first = low

    # Find the first element greater than x.
    low, high = first, n
    while low < high:
        mid = (low + high) // 2
        if arr[mid] <= x:
            low = mid + 1
        else:
            high = mid
    last = low

    return (last - first) > n // 2


